-- ============================================================
-- e-Cuti : Sistem Permohonan Cuti Kakitangan
-- Training database for the Day 2 migration workshop.
-- All people, identity numbers and addresses are invented.
-- Generated by tools/jana_data.py. Running this script again
-- drops and recreates every e-Cuti object in LegacyDb.
-- ============================================================
IF DB_ID('LegacyDb') IS NULL
    CREATE DATABASE LegacyDb;
GO
USE LegacyDb;
GO

IF OBJECT_ID('dbo.sp_LulusCuti', 'P') IS NOT NULL DROP PROCEDURE dbo.sp_LulusCuti;
IF OBJECT_ID('dbo.tblAuditLog', 'U') IS NOT NULL DROP TABLE dbo.tblAuditLog;
IF OBJECT_ID('dbo.tblPermohonanCuti', 'U') IS NOT NULL DROP TABLE dbo.tblPermohonanCuti;
IF OBJECT_ID('dbo.tblBakiCuti', 'U') IS NOT NULL DROP TABLE dbo.tblBakiCuti;
IF OBJECT_ID('dbo.tblCutiUmum', 'U') IS NOT NULL DROP TABLE dbo.tblCutiUmum;
IF OBJECT_ID('dbo.tblJenisCuti', 'U') IS NOT NULL DROP TABLE dbo.tblJenisCuti;
IF OBJECT_ID('dbo.tblStaf', 'U') IS NOT NULL DROP TABLE dbo.tblStaf;
IF OBJECT_ID('dbo.tblJabatan', 'U') IS NOT NULL DROP TABLE dbo.tblJabatan;
GO

CREATE TABLE dbo.tblJabatan (
    KodJabatan   char(3)      NOT NULL CONSTRAINT PK_tblJabatan PRIMARY KEY,
    NamaJabatan  varchar(60)  NOT NULL
);

CREATE TABLE dbo.tblStaf (
    NoStaf          varchar(10)  NOT NULL CONSTRAINT PK_tblStaf PRIMARY KEY,
    Nama            varchar(80)  NOT NULL,
    NoKP            varchar(14)  NULL,
    Emel            varchar(60)  NULL,
    KodJabatan      char(3)      NULL,
    Jawatan         varchar(60)  NULL,
    NoStafPenyelia  varchar(10)  NULL,
    KataLaluan      varchar(20)  NULL,
    Peranan         char(1)      NULL,   -- S = Staf, P = Penyelia, A = Pentadbir
    StatusAktif     char(1)      NULL,   -- Y / N
    TarikhLantikan  varchar(10)  NULL    -- hh/bb/tttt
);

CREATE TABLE dbo.tblJenisCuti (
    KodCuti        char(3)      NOT NULL CONSTRAINT PK_tblJenisCuti PRIMARY KEY,
    Keterangan     varchar(40)  NOT NULL,
    HadSetahun     int          NULL,
    PerluLampiran  char(1)      NULL,
    Susunan        int          NULL,
    StatusAktif    char(1)      NULL
);

CREATE TABLE dbo.tblCutiUmum (
    Tarikh      datetime     NOT NULL CONSTRAINT PK_tblCutiUmum PRIMARY KEY,
    Keterangan  varchar(60)  NULL
);

-- no primary key, no foreign keys (as found)
CREATE TABLE dbo.tblBakiCuti (
    NoStaf           varchar(10)   NULL,
    Tahun            int           NULL,
    KodCuti          char(3)       NULL,
    Kelayakan        int           NULL,
    BakiBawaHadapan  decimal(4,1)  NULL,
    Diambil          decimal(4,1)  NULL
);
CREATE INDEX IX_tblBakiCuti_NoStaf ON dbo.tblBakiCuti (NoStaf, Tahun);

CREATE TABLE dbo.tblPermohonanCuti (
    IdPermohonan    int IDENTITY(1,1) NOT NULL CONSTRAINT PK_tblPermohonanCuti PRIMARY KEY,
    NoStaf          varchar(10)   NULL,
    KodCuti         char(3)       NULL,
    TarikhMula      datetime      NULL,
    TarikhAkhir     datetime      NULL,
    BilHari         decimal(4,1)  NULL,
    Sebab           varchar(255)  NULL,
    Status          char(1)       NULL,   -- B = Baru, L = Lulus, T = Tolak, X = Batal
    TarikhMohon     datetime      NULL,
    NoStafPelulus   varchar(10)   NULL,
    TarikhLulus     datetime      NULL,
    CatatanPelulus  varchar(255)  NULL
);

CREATE TABLE dbo.tblAuditLog (
    IdLog       int IDENTITY(1,1) NOT NULL CONSTRAINT PK_tblAuditLog PRIMARY KEY,
    NoStaf      varchar(10)   NULL,
    Tindakan    varchar(20)   NULL,
    Butiran     varchar(255)  NULL,
    TarikhMasa  datetime      NULL,
    AlamatIP    varchar(40)   NULL
);
GO

-- Simpan keputusan pelulus. Jika lulus, tambah Diambil pada baki.
-- Cuti Kecemasan (CK) ditolak daripada baki Cuti Tahunan (CT).
CREATE PROCEDURE dbo.sp_LulusCuti
    @IdPermohonan   int,
    @NoStafPelulus  varchar(10),
    @Keputusan      char(1),
    @Catatan        varchar(255)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @NoStaf varchar(10), @KodCuti char(3), @Tahun int, @BilHari decimal(4,1);

    SELECT @NoStaf = NoStaf, @KodCuti = KodCuti, @Tahun = YEAR(TarikhMula), @BilHari = BilHari
    FROM dbo.tblPermohonanCuti
    WHERE IdPermohonan = @IdPermohonan AND Status = 'B';

    IF @NoStaf IS NULL
    BEGIN
        RAISERROR('Permohonan tidak dijumpai atau telah diproses.', 16, 1);
        RETURN;
    END

    UPDATE dbo.tblPermohonanCuti
    SET Status = @Keputusan,
        NoStafPelulus = @NoStafPelulus,
        TarikhLulus = GETDATE(),
        CatatanPelulus = NULLIF(@Catatan, '')
    WHERE IdPermohonan = @IdPermohonan;

    IF @Keputusan = 'L'
    BEGIN
        UPDATE dbo.tblBakiCuti
        SET Diambil = Diambil + @BilHari
        WHERE NoStaf = @NoStaf
          AND Tahun = @Tahun
          AND KodCuti = CASE WHEN @KodCuti = 'CK' THEN 'CT' ELSE @KodCuti END;
    END
END
GO

GO
SET IDENTITY_INSERT dbo.tblPermohonanCuti ON;
SET IDENTITY_INSERT dbo.tblPermohonanCuti OFF;
GO
GO

