UNION ALL SELECT 'tblCutiUmum', COUNT(*) FROM dbo.tblCutiUmum
UNION ALL SELECT 'tblBakiCuti', COUNT(*) FROM dbo.tblBakiCuti
UNION ALL SELECT 'tblPermohonanCuti', COUNT(*) FROM dbo.tblPermohonanCuti
UNION ALL SELECT 'tblAuditLog', COUNT(*) FROM dbo.tblAuditLog;
GO
